def count_good_triples():
    total_count = 0
    # x = 1 case
    total_count += 99 * 99

    # x > 1 case
    for x in range(2, 100):
        V = x + 1
        # Find prime factors of V
        prime_factors_V = []
        temp_V = V
        d = 2
        while d * d <= temp_V:
            if temp_V % d == 0:
                prime_factors_V.append(d)
                while temp_V % d == 0:
                    temp_V //= d
            d += 1
        if temp_V > 1:
            prime_factors_V.append(temp_V)

        # Factorization of V: V = product(p_i^b_i)
        factors_V = {}
        temp_V = V
        for p in prime_factors_V:
            count = 0
            while temp_V % p == 0:
                count += 1
                temp_V //= p
            factors_V[p] = count

        for z in range(1, 100):
            D = x**z + 1

            # Check if all prime factors of D divide V
            temp_D = D
            for p in prime_factors_V:
                while temp_D % p == 0:
                    temp_D //= p

            if temp_D == 1:
                # All prime factors of D divide V
                # D = product(p_i^a_i)
                # We need y_min = max(ceil(a_i / b_i))
                y_min = 0
                # We need to factor D now, but we know its only prime factors are in prime_factors_V
                temp_D = D
                for p in prime_factors_V:
                    a_i = 0
                    while temp_D % p == 0:
                        a_i += 1
                        temp_D //= p
                    b_i = factors_V[p]
                    y_min = max(y_min, (a_i + b_i - 1) // b_i)

                if y_min <= 99:
                    total_count += (99 - y_min + 1)

    return total_count

